/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']
# wooden block: brown ~ (90,70,60). Mask: R in 70-130, G in 50-100, B in 40-90, R>G>B
def brown_mask(f):
    r,g,b = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
    return (r>60)&(r<140)&(g>40)&(g<110)&(b>30)&(b<100)&(r>g+8)&(g>b+3)
for t in [0, 12, 24, 36, 48, 60, 72, 84, 95]:
    m = brown_mask(d[t])
    ys, xs = np.where(m)
    if len(xs):
        print(t, 'n=',m.sum(),'x',xs.min(),xs.max(),'y',ys.min(),ys.max())
    else:
        print(t, 'none')
\""
